CREATE OR REPLACE FUNCTION app_private.is_verified_member()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select exists (select 1 from auth.users where id = (select auth.uid()) and email_confirmed_at is not null);
$function$;

CREATE OR REPLACE FUNCTION app_private.is_admin()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
  select app_private.is_verified_member() and exists(
    select 1 from public.user_roles where user_id=(select auth.uid()) and role='admin'
  );
$function$;

CREATE OR REPLACE FUNCTION app_private.audit_admin_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  before_row jsonb := case when tg_op = 'INSERT' then null else to_jsonb(old) end;
  after_row jsonb := case when tg_op = 'DELETE' then null else to_jsonb(new) end;
  target text;
begin
  if tg_table_name = 'meetups'
    and tg_op = 'UPDATE'
    and not app_private.is_admin()
    and (to_jsonb(new) - array['confirmed_booking_count', 'updated_at'])
        is not distinct from (to_jsonb(old) - array['confirmed_booking_count', 'updated_at']) then
    return new;
  end if;

  target := coalesce(after_row ->> 'id', before_row ->> 'id', after_row ->> 'user_id', before_row ->> 'user_id');
  insert into public.admin_audit_log (actor_user_id, action, target_table, target_id, details)
  values (
    (select auth.uid()), lower(tg_op), tg_table_name, target,
    jsonb_strip_nulls(jsonb_build_object(
      'before', before_row - array['notes', 'note'],
      'after', after_row - array['notes', 'note']
    ))
  );
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION app_private.broadcast_question_state_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  owner_id uuid;
begin
  owner_id := coalesce(new.user_id, old.user_id);

  perform realtime.send(
    jsonb_build_object('changed', true),
    'question_state_changed',
    'question-state:' || owner_id::text,
    true
  );

  return null;
end;
$function$;

CREATE OR REPLACE FUNCTION app_private.enforce_booking_privacy_pause()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if not coalesce((select paused from app_private.privacy_protection_control where singleton),true)
     or app_private.is_admin() then return new; end if;
  if tg_op='UPDATE' then
    if new.user_id=auth.uid() and old.user_id=auth.uid()
       and old.status='confirmed' and new.status='cancelled'
       and (to_jsonb(new)-array['status','cancelled_at','updated_at']) =
           (to_jsonb(old)-array['status','cancelled_at','updated_at'])
    then return new; end if;
  end if;
  raise exception 'New bookings are temporarily paused' using errcode='42501';
end;
$function$;

CREATE OR REPLACE FUNCTION app_private.guard_booking_updates()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if (select auth.uid()) is not null and not app_private.is_admin() then
    if old.user_id <> (select auth.uid())
      or new.id <> old.id
      or new.user_id <> old.user_id
      or new.meetup_id <> old.meetup_id
      or new.booked_at <> old.booked_at
      or old.status <> 'confirmed'
      or new.status <> 'cancelled'
    then
      raise exception using
        errcode = '42501',
        message = 'Members may only cancel their own confirmed bookings';
    end if;
  end if;

  if new.status = 'cancelled' and old.status <> 'cancelled' then
    new.cancelled_at := now();
  elsif new.status = 'confirmed' then
    new.cancelled_at := null;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION app_private.guard_user_role_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if (select auth.uid()) is not null and not app_private.is_admin() then
    raise exception using errcode = '42501', message = 'Only an administrator may change user roles';
  end if;

  if tg_op in ('UPDATE', 'DELETE') and old.role = 'admin'
    and (tg_op = 'DELETE' or new.role <> 'admin')
    and (select count(*) from public.user_roles where role = 'admin') <= 1
  then
    raise exception using errcode = '23514', message = 'The final administrator cannot be removed';
  end if;

  if tg_op <> 'DELETE' and (select auth.uid()) is not null then
    new.assigned_by := (select auth.uid());
  end if;
  if tg_op = 'DELETE' then return old; end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION app_private.handle_new_auth_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  insert into public.profiles(id,display_name,email,onboarding_completed)
  values(new.id,left(nullif(btrim(coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name','')),''),80),new.email,false);
  insert into public.user_roles(user_id,role) values(new.id,'member');
  insert into public.notifications(user_id,audience_type,kind,title,body,entity_type,entity_id,target_url)
  select r.user_id,'admin','new_member','New member registered','A new member created an account.',
    'member',new.id,'/admin/?section=members&member='||new.id::text
  from public.user_roles r where r.role='admin';
  return new;
end;
$function$;

