CREATE OR REPLACE FUNCTION app_private.notify_booking_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  meetup_title text;
  member_name text;
  member_email text;
  meetup_timezone text;
  detail text;
  kind_name text;
  title_text text;
begin
  select m.title, coalesce(nullif(btrim(p.display_name), ''), 'Member'), coalesce(u.email::text, 'email unavailable'), coalesce(m.timezone, 'Europe/Moscow')
  into meetup_title, member_name, member_email, meetup_timezone
  from public.meetups m
  join auth.users u on u.id = new.user_id
  left join public.profiles p on p.id = new.user_id
  where m.id = new.meetup_id;

  if new.status = 'confirmed'
    and (tg_op = 'INSERT' or old.status <> 'confirmed') then
    kind_name := 'new_booking';
    title_text := 'New booking';
    detail := format('%s (%s) booked %s · %s.', member_name, member_email, meetup_title, to_char(new.booked_at at time zone meetup_timezone, 'Mon DD · HH24:MI'));
  elsif new.status = 'cancelled'
    and (tg_op = 'UPDATE' and old.status <> 'cancelled') then
    kind_name := 'booking_cancelled';
    title_text := 'Booking cancelled';
    detail := format('%s (%s) cancelled their booking for %s · booked %s.', member_name, member_email, meetup_title, to_char(new.booked_at at time zone meetup_timezone, 'Mon DD · HH24:MI'));
  else
    return new;
  end if;

  insert into public.notifications (user_id, kind, title, body, meetup_id, booking_id)
  select role_row.user_id, kind_name, title_text, left(detail, 1000), new.meetup_id, new.id
  from public.user_roles role_row
  where role_row.role = 'admin'
  on conflict (user_id, booking_id, kind) where booking_id is not null do nothing;

  insert into public.notifications (user_id, kind, title, body, meetup_id, booking_id)
  values (
    new.user_id,
    case when kind_name = 'new_booking' then 'booking_confirmed' else 'booking_cancelled' end,
    case when kind_name = 'new_booking' then 'Booking confirmed' else 'Booking cancelled' end,
    left(detail, 1000),
    new.meetup_id,
    new.id
  )
  on conflict (user_id, booking_id, kind) where booking_id is not null do nothing;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION app_private.notify_published_meetup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if new.status = 'published' and (tg_op = 'INSERT' or old.status is distinct from 'published') then
    insert into public.notifications (user_id, audience_type, kind, title, body, meetup_id, entity_type, entity_id, target_url)
    select r.user_id, 'all_members', 'new_meetup', 'A new GSC meetup is live',
      left(new.title, 100) || ' is now open to members.', new.id, 'meetup', new.id, '/meetups/?id=' || new.id::text
    from public.user_roles r where r.role = 'member'
    on conflict (user_id, meetup_id, kind) where meetup_id is not null do nothing;
  elsif new.status = 'cancelled' and (tg_op = 'INSERT' or old.status is distinct from 'cancelled') then
    insert into public.notifications (user_id, audience_type, kind, title, body, meetup_id, booking_id, entity_type, entity_id, target_url)
    select b.user_id, 'specific_user', 'meetup_cancelled', 'Meetup cancelled',
      left(new.title, 100) || ' has been cancelled. Your booking remains in your history.', new.id, b.id, 'meetup', new.id, '/meetups/?id=' || new.id::text
    from public.meetup_bookings b where b.meetup_id = new.id and b.status = 'confirmed'
    on conflict (user_id, booking_id, kind) where booking_id is not null do nothing;
  end if;
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION app_private.reconcile_loyalty_after_attendance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if tg_op = 'DELETE' then
    perform app_private.reconcile_loyalty_rewards(old.user_id);
    return old;
  end if;
  if tg_op = 'UPDATE' and old.user_id <> new.user_id then
    perform app_private.reconcile_loyalty_rewards(old.user_id);
  end if;
  perform app_private.reconcile_loyalty_rewards(new.user_id);
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION app_private.reconcile_loyalty_rewards(member_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  qualifying_count integer;
  target_count integer;
  redeemed_count integer;
  sequence_number integer;
  milestone_attendance_id uuid;
begin
  perform pg_advisory_xact_lock(hashtextextended(member_id::text, 0));

  select count(*)::integer into qualifying_count
  from public.attendance
  where user_id = member_id and status = 'attended' and is_paid = true;

  target_count := qualifying_count / 6;

  select count(*)::integer into redeemed_count
  from public.loyalty_rewards
  where user_id = member_id
    and issuance_source = 'automatic'
    and status = 'redeemed';

  if redeemed_count > target_count or exists (
    select 1 from public.loyalty_rewards
    where user_id = member_id
      and issuance_source = 'automatic'
      and status = 'redeemed'
      and reward_sequence > target_count
  ) then
    raise exception using
      errcode = '23514',
      message = 'This correction would invalidate an already redeemed loyalty reward';
  end if;

  for sequence_number in 1..target_count loop
    select id into milestone_attendance_id
    from public.attendance
    where user_id = member_id and status = 'attended' and is_paid = true
    order by recorded_at, id
    offset (sequence_number * 6) - 1 limit 1;

    insert into public.loyalty_rewards (
      user_id, reward_sequence, issuance_source, status,
      earned_after_attendance_id, required_attendance_count,
      reconciliation_voided
    ) values (
      member_id, sequence_number, 'automatic', 'available',
      milestone_attendance_id, 6, false
    )
    on conflict (user_id, reward_sequence) do update
    set earned_after_attendance_id = case
          when public.loyalty_rewards.status = 'redeemed'
            then public.loyalty_rewards.earned_after_attendance_id
          else excluded.earned_after_attendance_id
        end,
        status = case
          when public.loyalty_rewards.reconciliation_voided then 'available'
          else public.loyalty_rewards.status
        end,
        reconciliation_voided = false,
        updated_at = now();
  end loop;

  update public.loyalty_rewards
  set status = 'revoked', reconciliation_voided = true, updated_at = now()
  where user_id = member_id
    and issuance_source = 'automatic'
    and reward_sequence > target_count
    and status = 'available';
end;
$function$;

CREATE OR REPLACE FUNCTION app_private.redeem_free_reward_for_attendance()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  reward_id uuid;
begin
  if tg_op = 'UPDATE'
    and old.payment_status = 'free_reward'
    and new.payment_status <> 'free_reward'
    and exists (
      select 1 from public.loyalty_rewards
      where redeemed_booking_id = old.booking_id
        and user_id = old.user_id
        and status = 'redeemed'
    ) then
    raise exception using
      errcode = '23514',
      message = 'A redeemed free visit cannot be changed to a paid visit';
  end if;

  if new.status = 'attended'
    and new.payment_status = 'free_reward'
    and (tg_op = 'INSERT' or old.payment_status is distinct from new.payment_status) then
    if new.booking_id is null then
      raise exception using errcode = '23514', message = 'A free visit must reference a booking';
    end if;

    select id into reward_id
    from public.loyalty_rewards
    where user_id = new.user_id
      and status = 'available'
      and reward_type = 'free_meetup'
      and (expires_at is null or expires_at > now())
    order by reward_sequence
    for update skip locked
    limit 1;

    if reward_id is null then
      raise exception using errcode = 'P0001', message = 'No free meetup reward is available';
    end if;

    update public.loyalty_rewards
    set status = 'redeemed',
        redeemed_booking_id = new.booking_id,
        redeemed_at = now(),
        updated_at = now()
    where id = reward_id;
  end if;

  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION app_private.set_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  new.updated_at := now();
  return new;
end;
$function$;

CREATE OR REPLACE FUNCTION app_private.stamp_admin_managed_rows()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  actor uuid := (select auth.uid());
begin
  if actor is not null and not app_private.is_admin() then
    if tg_table_name <> 'meetups'
      or tg_op <> 'UPDATE'
      or (to_jsonb(new) - array['confirmed_booking_count', 'updated_at'])
         is distinct from (to_jsonb(old) - array['confirmed_booking_count', 'updated_at']) then
      raise exception using errcode = '42501', message = 'Administrator access required';
    end if;
    return new;
  end if;

  if tg_table_name = 'meetups' then
    if tg_op = 'INSERT' then new.created_by := actor; end if;
    new.updated_by := actor;
  elsif tg_table_name = 'attendance' then
    if tg_op = 'INSERT' or new.status is distinct from old.status then
      new.recorded_by := actor;
      new.recorded_at := now();
    end if;

    if new.payment_status = 'unpaid' and new.is_paid then
      new.payment_status := 'paid';
    end if;

    if new.payment_status = 'paid' then
      new.is_paid := true;
      if new.paid_currency is null then
        raise exception using errcode = '23514', message = 'Paid attendance requires a currency';
      end if;
      if tg_op = 'INSERT' or old.payment_status is distinct from new.payment_status
        or old.is_paid is distinct from new.is_paid
        or old.paid_amount_minor is distinct from new.paid_amount_minor
        or old.paid_currency is distinct from new.paid_currency
      then
        new.payment_recorded_by := actor;
        new.payment_recorded_at := now();
      end if;
    else
      new.is_paid := false;
      new.paid_amount_minor := null;
      new.paid_currency := null;
      new.payment_recorded_by := null;
      new.payment_recorded_at := null;
    end if;
  elsif tg_table_name = 'special_rewards' then
    if tg_op = 'INSERT' then new.issued_by := actor; end if;
    new.updated_by := actor;
  elsif tg_table_name in ('attendance_admin_notes', 'special_reward_admin_notes') then
    new.updated_by := actor;
  end if;
  return new;
end;
$function$;

